package app.devlens;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;
public class HomeWidget extends AppWidgetProvider{
 public void onUpdate(Context c,AppWidgetManager manager,int[] ids){String page=getClass().getSimpleName().equals("DiaryWidget")?"diary":getClass().getSimpleName().equals("AiWidget")?"ai":"music";String title=page.equals("diary")?"Дневник":page.equals("ai")?"Claude Opus 5.5":"Музыка";for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.home_widget);v.setTextViewText(R.id.widget_title,"MarkizApp · "+title);v.setTextColor(R.id.widget_title,0xffb5f56b);v.setTextViewText(R.id.widget_body,page.equals("diary")?c.getSharedPreferences("widgets",0).getString("diary","Добавить предметы и оценки"):"Открыть "+title);v.setTextColor(R.id.widget_body,0xffffffff);Intent i=new Intent(c,MainActivity.class).putExtra("page",page).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);v.setOnClickPendingIntent(R.id.widget_title,PendingIntent.getActivity(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));v.setOnClickPendingIntent(R.id.widget_body,PendingIntent.getActivity(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));v.setOnClickPendingIntent(R.id.widget_action,PendingIntent.getActivity(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));if(page.equals("music")&&(MusicService.state.equals("playing")||MusicService.state.equals("paused"))){boolean playing=MusicService.state.equals("playing");v.setTextViewText(R.id.widget_body,MusicService.track);v.setTextViewText(R.id.widget_action,playing?"Пауза":"Продолжить");Intent control=new Intent(c,MusicService.class).setAction(playing?"pause":"resume");v.setOnClickPendingIntent(R.id.widget_action,PendingIntent.getForegroundService(c,100000+id,control,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}manager.updateAppWidget(id,v);}}
}
